mapper.select:
SELECT u.id, u.car_type AS carType, u.car_color AS carColor, u.phone, u.register_time AS registerTime, u.status, u.audit_user_id AS auditUserId, u.audit_time AS auditTime, u.audit_comment AS auditComment, u.remark, u.reserve1, u.reserve2, u.creator, u.updater, u.create_time AS createTime, u.update_time AS updateTime, s.name AS stationName FROM unplate_enter u LEFT JOIN station_info s ON u.station_id = s.id WHERE u.deleted = 0
AND u.car_type = #{reqVO.carType}
AND u.car_color LIKE CONCAT('%', #{reqVO.carColor}, '%')
AND u.phone LIKE CONCAT('%', #{reqVO.phone}, '%')
AND u.status = #{reqVO.status}
AND u.station_id = #{reqVO.stationId}
AND u.audit_user_id = #{reqVO.auditUserId}
AND u.remark LIKE CONCAT('%', #{reqVO.remark}, '%')
AND u.register_time BETWEEN #{reqVO.registerTime[0]} AND #{reqVO.registerTime[1]}
ORDER BY u.id DESC

SELECT s.name AS stationName, COUNT(u.id) AS count FROM station_info s LEFT JOIN unplate_enter u ON u.station_id = s.id AND u.deleted = 0 AND u.register_time BETWEEN FROM_UNIXTIME(CAST(#{reqVO.startTime} AS UNSIGNED)) AND FROM_UNIXTIME(CAST(#{reqVO.endTime} AS UNSIGNED)) WHERE s.deleted = 0
AND s.id = #{reqVO.stationId}
GROUP BY s.id, s.name ORDER BY count DESC
